prompts.user:
/ [셋업] POS별 문항 풀에서 랜덤 인덱스(*_IDX) 추출
@SET(N_IDX, "@INDEX("@PRM_N@", "@PRM_N[.]@")@", SELF)@
@SET(V_IDX, "@INDEX("@PRM_V@", "@PRM_V[.]@")@", SELF)@
@SET(ADJ_IDX, "@INDEX("@PRM_ADJ@", "@PRM_ADJ[.]@")@", SELF)@

/ [셋업] 추출한 문항·정답(·보기)을 JSON_test_config에 기록
@UPJ(JSON_test_config.Noun[@R_i@].problem, "@EVAL(@R_i@)@. 파생어 그룹 @PRM_N[@N_IDX@]@의 기본형을 쓰시오.")@
@UPJ(JSON_test_config.Noun[@R_i@].problem_reference, "@PRM_N[@N_IDX@]@")@
@UPJ(JSON_test_config.Noun[@R_i@].answer, "@ANS_N[@N_IDX@]@")@

@UPJ(JSON_test_config.Verb[@R_i@].problem, "@EVAL(@R_i@)@. 파생어 그룹 @PRM_V[@V_IDX@]@의 기본형을 쓰시오.")@
@UPJ(JSON_test_config.Verb[@R_i@].problem_reference, "@PRM_V[@V_IDX@]@")@
@UPJ(JSON_test_config.Verb[@R_i@].answer, "@ANS_V[@V_IDX@]@")@

@UPJ(JSON_test_config.Adjective[@R_i@].problem, "@EVAL(@R_i@)@. 파생어 그룹 @PRM_ADJ[@ADJ_IDX@]@의 기본형을 쓰시오.")@
@UPJ(JSON_test_config.Adjective[@R_i@].problem_reference, "@PRM_ADJ[@ADJ_IDX@]@")@
@UPJ(JSON_test_config.Adjective[@R_i@].answer, "@ANS_ADJ[@ADJ_IDX@]@")@

// [채점] 학생 응답 정오 판정 후 점수·correctness 기록 (RWORD: 느슨한 단어 일치)

1. Noun
T/F boolean: @MAP("@TEXT(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",RWORD)@

Current Score: @JSON_test_config.Result[1].Noun@

Enumerated: @EVAL("@JSON_test_config.Result[1].Noun@ + @MAP("@TEXT(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",RWORD)@")@

update:
@UPJ(JSON_test_config.Result[1].Noun, @EVAL("@JSON_test_config.Result[1].Noun@ + @MAP("@TEXT(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",RWORD)@")@)@
@UPJ(JSON_test_config.Noun[@R_i@].Student_answer, "@TEXT(P_N@R_i@)@")@
@UPJ(JSON_test_config.Noun[@R_i@].correctness, @MAP("@TEXT(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",RWORD)@)@

2. Verb
T/F boolean: @MAP("@TEXT(P_V@R_i@)@", "@JSON_test_config.Verb[@R_i@].answer@", "1|0",RWORD)@

Current Score: @JSON_test_config.Result[1].Verb@

Enumerated: @EVAL("@JSON_test_config.Result[1].Verb@ + @MAP("@TEXT(P_V@R_i@)@", "@JSON_test_config.Verb[@R_i@].answer@", "1|0",RWORD)@")@

update:
@UPJ(JSON_test_config.Result[1].Verb, @EVAL("@JSON_test_config.Result[1].Verb@ + @MAP("@TEXT(P_V@R_i@)@", "@JSON_test_config.Verb[@R_i@].answer@", "1|0",RWORD)@")@)@
@UPJ(JSON_test_config.Verb[@R_i@].Student_answer, "@TEXT(P_V@R_i@)@")@
@UPJ(JSON_test_config.Verb[@R_i@].correctness, @MAP("@TEXT(P_V@R_i@)@", "@JSON_test_config.Verb[@R_i@].answer@", "1|0",RWORD)@)@

3. Adjective
T/F boolean: @MAP("@TEXT(P_ADJ@R_i@)@", "@JSON_test_config.Adjective[@R_i@].answer@", "1|0",RWORD)@

Current Score: @JSON_test_config.Result[1].Adjective@

Enumerated: @EVAL("@JSON_test_config.Result[1].Adjective@ + @MAP("@TEXT(P_ADJ@R_i@)@", "@JSON_test_config.Adjective[@R_i@].answer@", "1|0",RWORD)@")@

update:
@UPJ(JSON_test_config.Result[1].Adjective, @EVAL("@JSON_test_config.Result[1].Adjective@ + @MAP("@TEXT(P_ADJ@R_i@)@", "@JSON_test_config.Adjective[@R_i@].answer@", "1|0",RWORD)@")@)@
@UPJ(JSON_test_config.Adjective[@R_i@].Student_answer, "@TEXT(P_ADJ@R_i@)@")@
@UPJ(JSON_test_config.Adjective[@R_i@].correctness, @MAP("@TEXT(P_ADJ@R_i@)@", "@JSON_test_config.Adjective[@R_i@].answer@", "1|0",RWORD)@)@

// [집계] 인덱싱 보정(-1) 후 POS 점수 누적 합산(Cumulative)
@UPJ(JSON_test_config.Result[1].Noun, @EVAL("@JSON_test_config.Result[1].Noun@ - 1")@)@
@UPJ(JSON_test_config.Result[1].Verb, @EVAL("@JSON_test_config.Result[1].Verb@ - 1")@)@
@UPJ(JSON_test_config.Result[1].Adjective, @EVAL("@JSON_test_config.Result[1].Adjective@ - 1")@)@

@UPJ(JSON_test_config.Result[1].Cumulative, @EVAL("@JSON_test_config.Result[1].Noun@+@JSON_test_config.Result[1].Verb@+@JSON_test_config.Result[1].Adjective@")@)@
